public readonly struct Length : IEquatable<Length>
{
    private readonly double _metres;                     // canonical unit
    private Length(double metres) => _metres = metres;
    public static Length FromKilometers(double km) => new(km * 1_000);
    public static Length FromMeters(double m) => new(m);
    public double InFeet => _metres * 3.280839895;
    public static Length operator +(Length a, Length b) => new(a._metres + b._metres);
    public bool Equals(Length other) => _metres.Equals(other._metres);
}
